// Editorial sets retain the stored numeric level IDs; they are not proficiency scores.
export const SPECIES_PACKAGES=[
 {id:1,de:'Einstieg',en:'Getting started',descriptionDe:'Vertraute Arten aus Gärten, Parks, Wäldern, Feld und Gewässern – zum Beispiel Amsel, Kohlmeise und Stockente.',descriptionEn:'Familiar species from gardens, parks, woodland, farmland and watersides – for example Eurasian Blackbird, Great Tit and Mallard.'},
 {id:2,de:'Ausbau',en:'Building on the basics',descriptionDe:'Weitere Arten unterschiedlicher Lebensräume sowie Zug- und Wintergäste – zum Beispiel Neuntöter, Bekassine und Bergfink.',descriptionEn:'More species from varied habitats, plus passage migrants and winter visitors – for example Red-backed Shrike, Common Snipe and Brambling.'},
 {id:3,de:'Vertiefung',en:'Exploring further',descriptionDe:'Eine vielfältige Ergänzung, unter anderem mit Gebirgs- und Meeresvögeln sowie regional begrenzten Vorkommen – zum Beispiel Alpendohle, Basstölpel und Mauerläufer.',descriptionEn:'A varied additional set, including mountain birds, seabirds and species with restricted regional occurrence – for example Yellow-billed Chough, Northern Gannet and Wallcreeper.'}
];
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function speciesPackageControls(birds,selected,english){
 const language=english?'en':'de';
 return `<fieldset class="species-packages" aria-describedby="species-packages-help"><legend>${english?'Species packages':'Artenpakete'}</legend><p class="form-note" id="species-packages-help">${english?'Choose one or more packages. Each species belongs to exactly one package: “Building on the basics” and “Exploring further” add their own species and do not include earlier packages. These editorial sets are not difficulty ratings or your learning progress. Region, species groups and progress filters further narrow the selection. Counts and lists below show the complete packages before those filters.':'Wähle ein oder mehrere Pakete. Jede Art gehört zu genau einem Paket: „Ausbau“ und „Vertiefung“ ergänzen eigene Arten und enthalten die vorherigen Pakete nicht. Die redaktionelle Einteilung bewertet weder die Schwierigkeit noch deinen Lernstand. Region, Artengruppen und Lernstand schränken die Auswahl zusätzlich ein. Die Zahlen und Listen unten zeigen jeweils das vollständige Paket vor diesen Filtern.'}</p>${SPECIES_PACKAGES.map(p=>{
 const species=birds.filter(s=>s.level===p.id).sort((a,b)=>a[language].localeCompare(b[language],language));
 const title=english?p.en:p.de;
 return `<div class="species-package"><label class="check-row" for="species-package-${p.id}"><input id="species-package-${p.id}" name="levels" type="checkbox" value="${p.id}"${selected.includes(p.id)?' checked':''} aria-describedby="species-package-description-${p.id}"><strong>${esc(title)} · ${species.length} ${english?'species':'Arten'}</strong></label><p class="form-note" id="species-package-description-${p.id}">${esc(english?p.descriptionEn:p.descriptionDe)}</p><details><summary>${english?`Show all species in “${esc(title)}”`:`Alle Arten in „${esc(title)}“ anzeigen`}</summary><ul class="species-package-list" data-name-content lang="${language}">${species.map(s=>`<li>${esc(s[language])}</li>`).join('')}</ul></details></div>`;
 }).join('')}</fieldset>`;
}
